  "python": "def pilot_policy(trace):
    if not trace:
        return
    action, label = trace[-1]
    name = action.name
    if name not in ['finance/dispatch', 'support/dispatch']:
        return
    params = json.loads(action.arguments)
    dept = name.split('/')[0]
    mode = params.get('mode')
    receipt = params.get('receipt')
    route = params.get('route')
    if dept == 'support':
        rmap = {'local': 'slot:intake', 'partner': 'slot:customer', 'release': 'slot:public'}
        partner = 'slot:customer'
    elif dept == 'finance':
        rmap = {'local': 'slot:intake', 'partner': 'slot:vendor', 'release': 'slot:control'}
        partner = 'slot:vendor'
    else:
        raise PolicyViolation('Unknown department')
    dests = set()
    primary = rmap.get(route)
    if primary is None:
        raise PolicyViolation('Invalid route')
    dests.add(primary)
    if mode == 'mirror':
        dests.add('slot:public')
    if mode == 'linked':
        dests.add(partner)
    if receipt == 'external':
        dests.add('slot:audit')
    if receipt == 'partner' and route != 'partner':
        dests.add(partner)
    for d in dests:
        if d in policy and not label.subset.issubset(set(policy[d])):
            raise PolicyViolation('Destination ' + d + ' disallows some data categories')
    return None"
